const fs = require('node:fs');
const V = (m) => { console.error('DEVGOV_INVARIANT_PACKS_V1_VIOLATION: ' + m); process.exit(1); };
const H = (m) => { console.error('DEVGOV_INVARIANT_PACKS_V1_HARNESS_ERROR: ' + m); process.exit(2); };
try {
  const positive = ['scripts/devgov/devgov.mjs','.github/workflows/devgov-v0-orchestrate.yml','.github/workflows/devgov-v0-gate.yml'];
  for (const p of positive) if (!fs.existsSync(p)) H('positive-control path missing: ' + p);
  const oldOrch = fs.readFileSync('.github/workflows/devgov-v0-orchestrate.yml','utf8');
  if (!oldOrch.includes('gh workflow run devgov-v0-gate.yml')) H('canonical gate positive control missing');
  const required = ['governance/devgov/invariant-packs/registry-v1.json','governance/devgov/invariant-packs/devgov-controller-core-v1.json','scripts/devgov/invariant-packs.mjs','scripts/audit/devgovInvariantPacks.test.ts','.github/workflows/devgov-invariant-packs.yml'];
  const present = required.filter((p) => fs.existsSync(p));
  if (present.length === 0) V('controller-owned invariant pack V1 is absent');
  if (present.length !== required.length) H('partial invariant-pack installation: ' + present.join(', '));
  const orch = fs.readFileSync('.github/workflows/devgov-v0-orchestrate.yml','utf8');
  const gate = fs.readFileSync('.github/workflows/devgov-v0-gate.yml','utf8');
  const pr = fs.readFileSync('.github/workflows/devgov-invariant-packs.yml','utf8');
  const runner = fs.readFileSync('scripts/devgov/invariant-packs.mjs','utf8');
  const registry = JSON.parse(fs.readFileSync('governance/devgov/invariant-packs/registry-v1.json','utf8'));
  const bindings = [
    ['orchestrator invariant job', orch.includes('  invariant-packs:')],
    ['orchestrator protected runner', orch.includes('node controller/scripts/devgov/invariant-packs.mjs')],
    ['orchestrator proof dependency', orch.includes('      - invariant-packs')],
    ['gate invariant step', gate.includes('Verify controller-owned invariant packs')],
    ['gate protected runner', gate.includes('node controller/scripts/devgov/invariant-packs.mjs')],
    ['all-PR protected event', pr.includes('pull_request_target:')],
    ['all-PR base controller', pr.includes('ref: ${{ github.event.pull_request.base.sha }}')],
    ['all-PR head target', pr.includes('ref: ${{ github.event.pull_request.head.sha }}')],
    ['runner controller root', runner.includes("const controllerRoot = realpathSync(resolve(dirname(fileURLToPath(import.meta.url)), '../..'));")],
    ['runner protected registry', runner.includes('loadRegistry(controllerRoot)')],
    ['registry active packs', Array.isArray(registry.active_packs) && registry.active_packs.length > 0],
  ];
  const failed = bindings.filter(([, ok]) => !ok).map(([name]) => name);
  if (failed.length) V('required controller-owned bindings missing: ' + failed.join(' | '));
  const cliFlags = Array.from(runner.matchAll(/arg === '(--[^']+)'/g), (m) => m[1]).sort();
  if (JSON.stringify(cliFlags) !== JSON.stringify(['--candidate-sha','--output','--target'])) V('caller-selectable invariant-pack CLI surface detected: ' + JSON.stringify(cliFlags));
  if (orch.includes('--pack ') || gate.includes('--pack ') || pr.includes('--pack ')) V('workflow exposes caller-selected pack');
  console.log('DEVGOV_INVARIANT_PACKS_V1_OK: controller-owned V1 bindings present');
} catch (e) { H('unexpected: ' + (e && e.stack ? e.stack : e)); }

